```python
import math

def is_prime(n):
    if n == 1 or n <= 0 or n % 1 > 0:
        return False
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            return False
    return True

def is_fibonacci(n):
    if n < 0 or n % 1 > 0:
        return False
    x = 5 * n**2
    return math.isqrt(x + 4)**2 == (x + 4) or math.isqrt(x - 4)**2 == (x - 4)

def primes_and_fibos_product(arr):
    primes = []
    fibos = []
    result = 1

    for num in arr:
        if not isinstance(num, (int,float)) or isinstance(num, complex): 
            continue
        if is_prime(num) and len(primes) < 10:
            primes.append(num)
            result *= num
        if is_fibonacci(num) and len(fibos) < 10:
            fibos.append(num)
            result *= num

    return result
```

